let d = msg.payload;
flow.set("ultimaTelemetria", Date.now()); // usado pelo indicador de conexao do prototipo
let anteriores = flow.get("leiturasAnteriores") || {};

function tendencia(atual, anterior) {
    if (anterior === undefined || anterior === null) return "flat";
    if (atual > anterior) return "up";
    if (atual < anterior) return "down";
    return "flat";
}

let trends = {
    voltage: tendencia(d.voltage, anteriores.voltage),
    current: tendencia(d.current, anteriores.current),
    power: tendencia(d.power, anteriores.power),
    frequency: tendencia(d.frequency, anteriores.frequency),
    power_factor: tendencia(d.power_factor, anteriores.power_factor)
};

flow.set("leiturasAnteriores", d);

let limites = flow.get("limitesSeguranca") || { tensaoMin: 117, tensaoMax: 133, maxPower: 1500, maxCurrent: 11.8 };

function statusTensao(v) {
    if (v < limites.tensaoMin || v > limites.tensaoMax) return "danger";
    let margem = (limites.tensaoMax - limites.tensaoMin) * 0.1;
    if (v < limites.tensaoMin + margem || v > limites.tensaoMax - margem) return "warning";
    return "ok";
}

function statusLimite(atual, limite) {
    if (!limite) return "ok";
    let pct = atual / limite;
    if (pct >= 1) return "danger";
    if (pct >= 0.9) return "warning";
    return "ok";
}

let statusObj = {
    voltage: statusTensao(d.voltage),
    power: statusLimite(d.power, limites.maxPower),
    current: statusLimite(d.current, limites.maxCurrent)
};

let painel = Object.assign({}, d, { trends: trends, status: statusObj });

return [
    { payload: d.voltage, topic: "Tensão (V)" },
    { payload: d.current, topic: "Corrente (A)" },
    { payload: d.power, topic: "Potência (W)" },
    { payload: d.frequency, topic: "Frequência (Hz)" },
    { payload: d.power_factor, topic: "Fator de potência" },
    { payload: painel }
];

