        classe = "critico";
    } else if (sPotencia === "danger" || sCorrente === "danger") {
        label = "Sobrecarga";
        classe = "critico";
    } else if (sTensao === "warning" || sPotencia === "warning" || sCorrente === "warning") {
        label = "Atenção";
        classe = "atencao";
    }

    let horario = (row.data_hora || "").split(" ")[1] || row.data_hora;

    return {
        horario: horario,
        tensao: Number(row.voltage).toFixed(1) + " V",
        corrente: Number(row.current).toFixed(2) + " A",
        potencia: Math.round(row.power).toLocaleString("pt-BR") + " W",
        statusLabel: label,
        statusClass: classe
    };
});

msg.payload = linhas;
return msg;

let estado = msg.payload; // "ligada" ou "desligada"

let agora = new Date(new Date().toLocaleString("en-US", { timeZone: "America/Sao_Paulo" }));
let dataHora =
    agora.getFullYear() + "-" +
    String(agora.getMonth()+1).padStart(2,"0") + "-" +
    String(agora.getDate()).padStart(2,"0") + " " +
