return msg;

let eventos = msg.payload || [];

let agora = new Date(new Date().toLocaleString("en-US", { timeZone: "America/Sao_Paulo" }));

let segundosLigada = 0;
let segundosDesligada = 0;

for (let i = 0; i < eventos.length; i++) {
    let inicio = new Date(eventos[i].data_hora.replace(" ", "T") + "-03:00");
    let fim = (i + 1 < eventos.length)
        ? new Date(eventos[i + 1].data_hora.replace(" ", "T") + "-03:00")
        : agora;

    let duracaoSeg = (fim - inicio) / 1000;
    if (duracaoSeg < 0) duracaoSeg = 0;

    if (eventos[i].estado === "ligada") {
        segundosLigada += duracaoSeg;
    } else {
        segundosDesligada += duracaoSeg;
    }
}
// Observação: o intervalo entre meia-noite e o primeiro evento do dia não é
// contabilizado, pois não há garantia do estado da carga antes do primeiro evento.

function paraHorasMinutos(seg) {
    let h = Math.floor(seg / 3600);
    let m = Math.round((seg % 3600) / 60);
    return h + "h " + m + "min";
}

let totalSeg = segundosLigada + segundosDesligada;
let pctLigada = totalSeg > 0 ? Math.round((segundosLigada / totalSeg) * 100) : 0;

msg.distribuicao = {
    pctLigada: pctLigada,
    ligadaTexto: paraHorasMinutos(segundosLigada),
    desligadaTexto: paraHorasMinutos(segundosDesligada)
};

msg.topic = "SELECT MAX(power) as pico FROM telemetria WHERE data_hora >= date('now','-3 hours') AND data_hora < date('now','-3 hours','+1 day')";
return msg;

let pico = (msg.payload && msg.payload[0] && msg.payload[0].pico != null)
    ? Math.round(msg.payload[0].pico) : 0;

let dist = msg.distribuicao || { pctLigada: 0, ligadaTexto: "0h 0min", desligadaTexto: "0h 0min" };

msg.payload = {
    pctLigada: dist.pctLigada,
    ligadaTexto: dist.ligadaTexto,
    desligadaTexto: dist.desligadaTexto,
    picoTexto: pico.toLocaleString("pt-BR") + " W"
};
return msg;

let e = msg.payload;
if (typeof e === "string") {
    try { e = JSON.parse(e); } catch (err) { node.error("Evento invalido: " + msg.payload); return null; }
}

const validos = ["ligada", "desligada", "reinicio", "reconexao", "falha_medidor", "medidor_ok"];
if (!e || validos.indexOf(e.evento) === -1) {
    node.warn("Evento ignorado: " + JSON.stringify(e));
    return null;
}

// ---- Controle do temporizador apos desligamento por protecao / reinicio / reconexao ----
// Apos um desligamento por protecao a carga NAO e religada sozinha ate alguem (ou a proxima
// janela do temporizador) enviar um novo "ligar".
if (e.evento === "desligada" && e.origem === "protecao") flow.set("bloqueioProtecao", true);
if (e.evento === "ligada") flow.set("bloqueioProtecao", false);

if (e.evento === "reinicio" || e.evento === "reconexao") {
    let modo = flow.get("modo_operacao") || "manual";
    if (modo === "temporizador" && !flow.get("bloqueioProtecao")) {
        // forca o VERIFICADOR TEMPORIZADOR a reenviar o estado desejado (ate 10 s)
        flow.set("estadoDesejadoTemporizador", null);
        node.warn("Temporizador: ressincronizando apos " + e.evento);
    }
}

// reconexao serve so para ressincronizar: nao entra no historico
if (e.evento === "reconexao") return null;

const esc = s => String(s === undefined || s === null ? "" : s).replace(/'/g, "''");

let agora = new Date(new Date().toLocaleString("en-US", { timeZone: "America/Sao_Paulo" }));
let dataHora =
    agora.getFullYear() + "-" +
    String(agora.getMonth()+1).padStart(2,"0") + "-" +
