msg.topic = `INSERT INTO eventos_carga (data_hora, evento, origem, detalhe) VALUES ('${dataHora}', '${esc(e.evento)}', '${esc(e.origem || "manual")}', '${esc(e.detalhe)}')`;
return msg;

const filtro = flow.get("filtroEventos") || "todos";
let where = "";
if (filtro === "manual") where = "WHERE origem IN ('dashboard','whatsapp','botao_fisico','manual')";
else if (filtro === "temporizador") where = "WHERE origem = 'temporizador'";
else if (filtro === "protecao") where = "WHERE origem = 'protecao'";
else if (filtro === "sistema") where = "WHERE origem = 'sistema'";

