    manual: "Manual",
    temporizador: "Temporizador",
    protecao: "Proteção automática",
    sistema: "Sistema",
    boot: "Inicialização"
};
const eventoTxt = {
    ligada:        { texto: "Ligada",           classe: "on"  },
    desligada:     { texto: "Desligada",        classe: "off" },
    reinicio:      { texto: "Reinício",         classe: "sys" },
    falha_medidor: { texto: "Falha do medidor", classe: "prot" },
