    sobrecarga_potencia: "Sobrecarga de potência"
};

let linhas = (msg.payload || []).map(r => {
    let partes = (r.data_hora || "").split(" ");
    let data = partes[0] ? partes[0].split("-").reverse().join("/") : "";
