    };
});

msg.payload = linhas;
return msg;

// Horarios de envio do relatorio (horario de Brasilia)
const HORARIOS = [8, 20];

let agora = new Date(new Date().toLocaleString("en-US", { timeZone: "America/Sao_Paulo" }));
let hh = agora.getHours();
let mm = agora.getMinutes();

