// ===== Configuracao da retencao =====
const HORA_EXECUCAO        = 3;    // roda uma vez por dia, entre 03:00 e 03:59 (Brasilia)
const DIAS_ESTADO_CARGA    = 90;   // estado_carga so alimenta o grafico do dia
const DIAS_EVENTOS         = 365;  // historico de acionamentos
const DIAS_COMPACTAR_CUSTO = 30;   // custo_energia: mantem 1 linha/dia apos esse prazo
// telemetria NAO e apagada: e a base dos graficos de consumo e historico de grandezas.

let agora = new Date(new Date().toLocaleString("en-US", { timeZone: "America/Sao_Paulo" }));
if (agora.getHours() !== HORA_EXECUCAO) return null;

let dia =
    agora.getFullYear() + "-" +
    String(agora.getMonth() + 1).padStart(2, "0") + "-" +
    String(agora.getDate()).padStart(2, "0");
if (flow.get("ultimaLimpeza") === dia) return null;
flow.set("ultimaLimpeza", dia);

const limite = (dias) => `date('now','-3 hours','-${dias} days')`;

const sqls = [
    `DELETE FROM estado_carga WHERE data_hora < ${limite(DIAS_ESTADO_CARGA)}`,
    `DELETE FROM eventos_carga WHERE data_hora < ${limite(DIAS_EVENTOS)}`,
    // mantem, por dia, a linha de maior custo (a mesma que os graficos usam via MAX)
    `DELETE FROM custo_energia
       WHERE data_hora < ${limite(DIAS_COMPACTAR_CUSTO)}
         AND id NOT IN (
            SELECT id FROM (
                SELECT id, ROW_NUMBER() OVER (
                    PARTITION BY date(data_hora) ORDER BY custo_reais DESC, id DESC
                ) AS rn
                FROM custo_energia
                WHERE data_hora < ${limite(DIAS_COMPACTAR_CUSTO)}
            ) WHERE rn = 1
         )`
];

node.warn("Rotina de limpeza do banco executada (" + dia + ")");
return [sqls.map(q => ({ topic: q }))];

const esc = v => {
    v = (v === null || v === undefined) ? "" : String(v);
    return /[";\r\n]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v;
};

let linhas = [["Data/Hora", "Evento", "Origem", "Detalhe"].join(";")];
(msg.payload || []).forEach(r => {
    linhas.push([r.data_hora, r.evento, r.origem, r.detalhe].map(esc).join(";"));
});

let agora = new Date(new Date().toLocaleString("en-US", { timeZone: "America/Sao_Paulo" }));
