return msg;

let dias = parseInt(msg.req && msg.req.query ? msg.req.query.dias : "", 10);
if (isNaN(dias) || dias < 1) dias = 7;
if (dias > 31) dias = 31;   // limite para nao estourar a memoria

msg.topic = `SELECT data_hora, voltage, current, power, energy_kwh, frequency, power_factor
FROM telemetria
WHERE data_hora >= datetime('now','-3 hours','-${dias} days')
ORDER BY data_hora ASC`;
msg.dias = dias;
return msg;

const num = v => (v === null || v === undefined) ? "" : String(v).replace(".", ",");

let linhas = [["Data/Hora", "Tensao (V)", "Corrente (A)", "Potencia (W)", "Energia (kWh)", "Frequencia (Hz)", "Fator de potencia"].join(";")];
(msg.payload || []).forEach(r => {
    linhas.push([r.data_hora, num(r.voltage), num(r.current), num(r.power), num(r.energy_kwh), num(r.frequency), num(r.power_factor)].join(";"));
