let agora = new Date(new Date().toLocaleString("en-US", { timeZone: "America/Sao_Paulo" }));
let ymd = agora.getFullYear() + String(agora.getMonth() + 1).padStart(2, "0") + String(agora.getDate()).padStart(2, "0");

msg.payload = "\ufeff" + linhas.join("\r\n");
msg.headers = {
    "Content-Type": "text/csv; charset=utf-8",
    "Content-Disposition": `attachment; filename="telemetria_${msg.dias}d_${ymd}.csv"`
};
msg.statusCode = 200;
return msg;

// A Evolution v2 repete o webhook se nao receber resposta HTTP.
// Responde 200 na hora, antes de qualquer processamento.
msg.payload = "ok";
msg.statusCode = 200;
return msg;

const s = msg.status || {};
let estado = "warn", texto = "Conectando...";
if (s.fill === "green")       { estado = "ok";  texto = "Conectado ao broker HiveMQ"; }
else if (s.fill === "red")    { estado = "off"; texto = "Desconectado do broker"; }
else if (s.fill === "yellow") { estado = "warn"; texto = "Reconectando..."; }
flow.set("statusMqtt", { estado: estado, texto: texto });
return null;

let estado = "off", texto = "Sem resposta da Evolution API";

if (msg.error) {
    texto = "Evolution API inacessível";
} else {
    const code = msg.statusCode;
    const st = msg.payload && msg.payload.instance && msg.payload.instance.state;
    if (code === 200 && st === "open")      { estado = "ok";   texto = "Conectado"; }
    else if (st === "connecting")           { estado = "warn"; texto = "Conectando ao WhatsApp..."; }
    else if (st === "close")                { estado = "off";  texto = "Desconectado: escaneie o QR Code"; }
    else if (code === 401)                  { texto = "Chave da Evolution inválida"; }
    else if (code === 404)                  { texto = "Instância não encontrada"; }
}
flow.set("statusWhats", { estado: estado, texto: texto });
return null;

msg.headers = { "apikey": env.get("EVOLUTION_API_KEY") };
msg.payload = "";
return msg;

const agora = Date.now();
const fmtIdade = s => s < 60 ? Math.round(s) + " s" : (s < 3600 ? Math.floor(s / 60) + " min" : Math.floor(s / 3600) + " h");

const mqtt  = flow.get("statusMqtt")  || { estado: "warn", texto: "Verificando..." };
const whats = flow.get("statusWhats") || { estado: "warn", texto: "Verificando..." };

// Prototipo (ESP32): idade da ultima telemetria (publicada a cada 10 s)
const ult = flow.get("ultimaTelemetria");
let esp;
if (mqtt.estado !== "ok") {
    esp = { estado: "warn", texto: "Indeterminado (sem conexão com o broker)" };
} else if (!ult) {
    esp = { estado: "off", texto: "Sem leituras recebidas" };
} else {
    const idade = (agora - ult) / 1000;
    if (idade <= 30)      esp = { estado: "ok",   texto: "Online · última leitura há " + fmtIdade(idade) };
    else if (idade <= 90) esp = { estado: "warn", texto: "Sem leituras há " + fmtIdade(idade) };
    else                  esp = { estado: "off",  texto: "Offline · última leitura há " + fmtIdade(idade) };
}

msg.payload = { mqtt: mqtt, esp: esp, whats: whats };
return msg;

const GRUPO = env.get("WHATSAPP_GRUPO");   // grupo do bot
const TIMEOUT_MS = 10000;          // tempo de espera pela confirmacao do prototipo

// payload esperado: "ligar|whatsapp" ou "desligar|dashboard"
const partes = String(msg.payload || "").split("|");
const cmd = partes[0];
const origem = partes[1] || "";
if (cmd !== "ligar" && cmd !== "desligar") return null;
if (origem !== "whatsapp" && origem !== "dashboard") return null;

const id = Date.now();
flow.set("cmdPendente", { id: id, cmd: cmd, origem: origem });

setTimeout(function () {
    const p = flow.get("cmdPendente");
    if (!p || p.id !== id) return;   // ja houve retorno, ou existe um comando mais recente
    flow.set("cmdPendente", null);

    let ultima = "";
    const ult = flow.get("ultimaTelemetria");
    if (ult) {
        const s = (Date.now() - ult) / 1000;
        ultima = "\nÚltima leitura recebida: há " + (s < 60 ? Math.round(s) + " s" : (s < 3600 ? Math.floor(s / 60) + " min" : Math.floor(s / 3600) + " h")) + ".";
    }

    const textoWhats =
`⚠️ SEM RETORNO DO PROTÓTIPO

O comando "${cmd}" foi enviado, mas o protótipo não respondeu em ${TIMEOUT_MS / 1000} s.${ultima}

Verifique se ele está energizado e conectado ao Wi-Fi.`;

    const textoDash = `Sem retorno do protótipo ao comando "${cmd}". Verifique se ele está energizado e conectado.`;

    node.send([
        { payload: { number: GRUPO, text: textoWhats } },
        { payload: textoDash }
    ]);
}, TIMEOUT_MS);

return null;

// O prototipo publica o estado ("ligada"/"desligada") sempre que executa um comando.
const p = flow.get("cmdPendente");
if (!p) return null;

const estado = String(msg.payload).trim().toLowerCase();
const esperado = (p.cmd === "ligar") ? "ligada" : "desligada";
if (estado === esperado) flow.set("cmdPendente", null);

return null;
